import {appendOrderSummaryInfo,appendOrderSummaryState} from './admin-order-summary.mjs';
import {mockupsForPfOrder,appendMockupOverview} from './admin-mockups.mjs';
import {nextStep,isTestOrder,dateTime,paymentLabel} from './admin-order-state.mjs';
export function workQueue(orders,checkouts,mailRows=[]){return orders.filter(o=>!isTestOrder(o,checkouts.find(c=>c.id===o.checkoutId))).map(order=>{const checkout=checkouts.find(c=>c.id===order.checkoutId),[owner,next]=nextStep(order,checkout,mailRows),blockers=[...(checkout?.finance?.problems||[]),...(order.proofIntakeProblems||[])];
 if(['needs_attention','needs_reconciliation'].includes(order.status))blockers.push(order.pfStatusInformation||'Afklar PF-status og hændelseslog.');
 if(checkout&&['authorization_expired','capture_reconciliation','payment_failed'].includes(checkout.status))blockers.push(paymentLabel(checkout));
 if(order.lines?.some(l=>l.decorations?.length)&&!mockupsForPfOrder(checkout,order).length)blockers.push('Kontrollér designvisning og mockups på ordren.');
 if(['shipped','partially_shipped'].includes(order.status)&&!order.shipment?.trackingDetails?.some(t=>t.trackingURL))blockers.push('Trackinglink mangler.');
 return {order,checkout,owner,next,blockers,bucket:['shipped','partially_shipped'].includes(order.status)?'deliveries':['approval_recorded','processing','confirmed'].includes(order.status)?'production':['awaiting_proof','proof_received','revision_requested','approval_pending_pf'].includes(order.status)?'proofs':'orders'};});}
const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
export function renderWorkQueue(container,orders,checkouts,view='overview',mailRows=[]){const rows=workQueue(orders,checkouts,mailRows),active=rows.filter(r=>r.order.status!=='cancelled');if(['overview','actions','blocked','deliveries'].includes(view))for(const mail of mailRows.filter(m=>m.status!=='sent'&&(view!=='blocked'||['blocked','failed','uncertain'].includes(m.status)))){const card=el('article');card.className='panel';const a=el('a','Åbn forsendelse →');a.href='/admin/pf-orders#order='+mail.orderId;card.append(el('strong',mail.status==='review'?'Forsendelsesmail klar til gennemgang':'Forsendelsesmail kræver handling'),el('p',(mail.problems||[]).join(' ')||mail.error||mail.to),a);container.append(card);}

 const filtered=active.filter(r=>view==='overview'||view==='actions'?r.owner==='Smerch'||r.blockers.length:view==='blocked'?r.blockers.length:r.bucket===view);
 for(const r of filtered){const card=el('article');card.className='order-summary-card';const gallery=el('div'),info=el('div'),state=el('div');appendMockupOverview(gallery,mockupsForPfOrder(r.checkout,r.order),{decorated:r.order.lines?.some(l=>l.decorations?.length)});appendOrderSummaryInfo(info,{checkout:r.checkout,orders:[r.order],lines:r.order.lines});appendOrderSummaryState(state,r.checkout,[r.order]);if(r.owner==='Smerch')state.append(el('p',r.next));for(const issue of r.blockers)if(!r.next.includes(issue))state.append(el('p',issue));const open=el('a','Åbn ordre →');open.className='action';open.href='/admin/pf-orders#order='+encodeURIComponent(r.order.id);state.append(open);card.append(gallery,info,state);container.append(card);}if(!filtered.length)container.append(el('p',({proofs:'Ingen korrekturer i denne visning.',production:'Ingen ordrer i produktion.',deliveries:'Ingen registrerede leveringer.',blocked:'Ingen blokeringer registreret.'}[view]||'Ingen ordrer kræver din handling lige nu.')));
 if(['overview','actions','blocked'].includes(view))for(const c of checkouts.filter(c=>!c.adminTest&&!orders.some(o=>o.checkoutId===c.id)&&['authorized','capture_reconciliation'].includes(c.status))){const p=el('p'),a=el('a','Åbn ordre og betalingsdetaljer');a.href='/admin#orders';p.append(document.createTextNode('Ordre uden PF-tilknytning: '+(c.shipping?.name||c.id)+' · '+(c.pfHandoff?.reason||paymentLabel(c))+' '),a);container.append(p);}
}

export function queueCounts(orders,checkouts,mailRows=[]){const rows=workQueue(orders,checkouts,mailRows).filter(r=>r.order.status!=='cancelled'),actions=new Set(rows.filter(r=>r.owner==='Smerch'||r.blockers.length).map(r=>r.order.id)),blocked=new Set(rows.filter(r=>r.blockers.length).map(r=>r.order.id));for(const m of mailRows.filter(m=>m.status!=='sent')){actions.add(m.orderId);if(['blocked','failed','uncertain'].includes(m.status))blocked.add(m.orderId);}const unlinked=checkouts.filter(c=>!c.adminTest&&!orders.some(o=>o.checkoutId===c.id)&&['authorized','capture_reconciliation'].includes(c.status));for(const c of unlinked){actions.add(c.id);blocked.add(c.id);}return {overview:actions.size,orders:new Set(rows.map(r=>r.order.checkoutId||r.order.id)).size+unlinked.length,proofs:rows.filter(r=>r.bucket==='proofs').length,production:rows.filter(r=>r.bucket==='production').length,deliveries:rows.filter(r=>r.bucket==='deliveries').length,blocked:blocked.size};}
